// Standalone repro page for weather-pin flicker: bare-bones deck.gl attribute
// transitions, no MapLibre. See requirements/weather-pin-flicker-debug.md (experiment E3).
// Minimal case: ScatterplotLayer + single getFillColor transition + static data.
import { Deck } from '@deck.gl/core';
import { IconLayer, ScatterplotLayer } from '@deck.gl/layers';

const PIN_RADIUS_PX = 13;

const ICON_MAPPING = {
  dot: { x: 0, y: 0, width: PIN_RADIUS_PX * 2, height: PIN_RADIUS_PX * 2, anchorX: PIN_RADIUS_PX, anchorY: PIN_RADIUS_PX, mask: true }
};

function buildIconAtlas() {
  const canvas = document.createElement('canvas');
  canvas.width = PIN_RADIUS_PX * 2;
  canvas.height = PIN_RADIUS_PX * 2;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.arc(PIN_RADIUS_PX, PIN_RADIUS_PX, PIN_RADIUS_PX, 0, Math.PI * 2);
  ctx.fill();
  return canvas;
}

const ICON_ATLAS = buildIconAtlas();

const CENTER = [174.8, -36.85];
const N_PINS = 40;

const stations = [];
for (let i = 0; i < N_PINS; i++) {
  stations.push({
    position: [CENTER[0] + (Math.random() - 0.5) * 0.4, CENTER[1] + (Math.random() - 0.5) * 0.3],
    color: [Math.floor(Math.random() * 255), Math.floor(Math.random() * 200), 80, 180]
  });
}

let useTransitions = true;
let useIconLayer = false;
let dataVersion = 0;

function randomColor() {
  return [Math.floor(Math.random() * 255), Math.floor(Math.random() * 200), 80, 180];
}

function shuffleColors() {
  for (const s of stations) s.color = randomColor();
  dataVersion++;
  redraw();
}

function makeLayer() {
  if (useIconLayer) {
    return new IconLayer({
      id: 'test-icon',
      data: stations,
      iconAtlas: ICON_ATLAS,
      iconMapping: ICON_MAPPING,
      sizeUnits: 'pixels',
      transitions: useTransitions ? { getColor: 300 } : undefined,
      getPosition: d => d.position,
      getIcon: () => 'dot',
      getSize: PIN_RADIUS_PX * 2,
      getColor: d => d.color,
      updateTriggers: { getColor: dataVersion }
    });
  }
  return new ScatterplotLayer({
    id: 'test-scatter',
    data: stations,
    radiusUnits: 'pixels',
    transitions: useTransitions ? { getFillColor: 300 } : undefined,
    getPosition: d => d.position,
    getRadius: PIN_RADIUS_PX,
    getFillColor: d => d.color,
    updateTriggers: { getFillColor: dataVersion }
  });
}

const deck = new Deck({
  parent: document.getElementById('deck-container'),
  initialViewState: { longitude: CENTER[0], latitude: CENTER[1], zoom: 10 },
  controller: true,
  layers: [makeLayer()]
});

function redraw() {
  deck.setProps({ layers: [makeLayer()] });
}

document.getElementById('chk-transitions').addEventListener('change', e => {
  useTransitions = e.target.checked;
  redraw();
});

document.getElementById('chk-icon').addEventListener('change', e => {
  useIconLayer = e.target.checked;
  redraw();
});

document.getElementById('btn-shuffle').addEventListener('click', shuffleColors);

let autoTimer = null;
document.getElementById('chk-auto').addEventListener('change', e => {
  if (e.target.checked) autoTimer = setInterval(shuffleColors, 2000);
  else { clearInterval(autoTimer); autoTimer = null; }
});

const gl = document.createElement('canvas').getContext('webgl2');
const dbg = gl?.getExtension('WEBGL_debug_renderer_info');
document.getElementById('gl-info').textContent = dbg
  ? gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL)
  : 'renderer info unavailable';
